/*
 * SMARTWORK 360 — minimal offline shell service worker.
 * Deliberately hand-written instead of generated by next-pwa (see DECISIONS.md 0.8).
 * Strategy: cache-first for same-origin static assets, network-only for /api.
 */
const CACHE = 'smartwork360-v2';
const PRECACHE = ['/', '/login', '/manifest.webmanifest', '/brand/mark.svg', '/brand/mark-white.svg'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(PRECACHE).catch(() => undefined))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  // Never serve stale API data — dashboards must always reflect the live chain.
  if (url.pathname.startsWith('/api')) return;

  event.respondWith(
    caches.match(request).then(
      (cached) =>
        cached ||
        fetch(request)
          .then((response) => {
            if (response.ok && response.type === 'basic') {
              const copy = response.clone();
              caches.open(CACHE).then((cache) => cache.put(request, copy));
            }
            return response;
          })
          .catch(() => caches.match('/')),
    ),
  );
});
